import itertools

def is_magic(seq):
    n = len(seq)
    for i in range(n):
        if seq[i] != seq.count(i):
            return False
    return True

def find_magic_sequence(n):
    # The sum of x_i must be n
    # The sum of i * x_i must be n
    # x_i can range from 0 to n

    # We can use backtracking or just iterate through possible combinations
    # Since n=7, the search space is not too large.
    # Actually, the sum of x_i = 7 and sum of i*x_i = 7 is a strong constraint.

    for seq in itertools.product(range(n + 1), repeat=n):
        if sum(seq) == n and sum(i * seq[i] for i in range(n)) == n:
            if is_magic(seq):
                return seq
    return None

print(find_magic_sequence(7))
